1	#!/usr/bin/env bun
2	/**
3	 * ncl — NanoClaw CLI client (container edition).
4	 *
5	 * Same interface as the host-side `bin/ncl`. Detects that it's inside a
6	 * container (the session DBs exist at /workspace/) and uses a DB transport
7	 * instead of the Unix socket transport.
8	 *
9	 * Writes a cli_request system message to outbound.db, polls inbound.db
10	 * for the response. Self-contained — no imports from agent-runner.
11	 */
12	import { Database } from 'bun:sqlite';
13	
14	// ---------------------------------------------------------------------------
15	// Frame types (mirrors src/cli/frame.ts on the host)
16	// ---------------------------------------------------------------------------
17	
18	type RequestFrame = {
19	  id: string;
20	  command: string;
21	  args: Record<string, unknown>;
22	};
23	
24	type ResponseFrame =
25	  | { id: string; ok: true; data: unknown }
26	  | { id: string; ok: false; error: { code: string; message: string } };
27	
28	// ---------------------------------------------------------------------------
29	// Paths
30	// ---------------------------------------------------------------------------
31	
32	const INBOUND_DB = '/workspace/inbound.db';
33	const OUTBOUND_DB = '/workspace/outbound.db';
34	
35	// ---------------------------------------------------------------------------
36	// DB transport
37	// ---------------------------------------------------------------------------
38	
39	function generateId(): string {
40	  return `cli-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
41	}
42	
43	/**
44	 * Write a cli_request to outbound.db.
45	 *
46	 * Uses BEGIN IMMEDIATE to acquire a write lock before reading max(seq),
47	 * preventing seq collisions with concurrent agent-runner writes.
48	 */
49	function writeRequest(req: RequestFrame): void {
50	  const db = new Database(OUTBOUND_DB);
51	  db.exec('PRAGMA journal_mode = DELETE');
52	  db.exec('PRAGMA busy_timeout = 5000');
53	
54	  const inDb = new Database(INBOUND_DB, { readonly: true });
55	  inDb.exec('PRAGMA busy_timeout = 5000');
56	
57	  try {
58	    db.exec('BEGIN IMMEDIATE');
59	    const maxOut = (db.prepare('SELECT COALESCE(MAX(seq), 0) AS m FROM messages_out').get() as { m: number }).m;
60	    const maxIn = (inDb.prepare('SELECT COALESCE(MAX(seq), 0) AS m FROM messages_in').get() as { m: number }).m;
61	    const max = Math.max(maxOut, maxIn);
62	    const nextSeq = max % 2 === 0 ? max + 1 : max + 2;
63	
64	    db.prepare(
65	      `INSERT INTO messages_out (id, seq, timestamp, kind, content)
66	       VALUES ($id, $seq, datetime('now'), 'system', $content)`,
67	    ).run({
68	      $id: req.id,
69	      $seq: nextSeq,
70	      $content: JSON.stringify({
71	        action: 'cli_request',
72	        requestId: req.id,
73	        command: req.command,
74	        args: req.args,
75	      }),
76	    });
77	    db.exec('COMMIT');
78	  } catch (e) {
79	    db.exec('ROLLBACK');
80	    throw e;
81	  } finally {
82	    inDb.close();
83	    db.close();
84	  }
85	}
86	
87	/**
88	 * Poll inbound.db for a cli_response matching our requestId.
89	 * Opens a fresh connection each poll (mmap_size=0) for cross-mount visibility.
90	 */
91	function pollResponse(requestId: string, timeoutMs: number): ResponseFrame | null {
92	  const deadline = Date.now() + timeoutMs;
93	
94	  while (Date.now() < deadline) {
95	    const inDb = new Database(INBOUND_DB, { readonly: true });
96	    inDb.exec('PRAGMA busy_timeout = 5000');
97	    inDb.exec('PRAGMA mmap_size = 0');
98	
99	    try {
100	      const row = inDb
101	        .prepare("SELECT id, content FROM messages_in WHERE status = 'pending' AND content LIKE ?")
102	        .get(`%"requestId":"${requestId}"%`) as { id: string; content: string } | null;
103	
104	      if (row) {
105	        // Mark as completed via processing_ack so agent-runner skips it
106	        const outDb = new Database(OUTBOUND_DB);
107	        outDb.exec('PRAGMA journal_mode = DELETE');
108	        outDb.exec('PRAGMA busy_timeout = 5000');
109	        outDb
110	          .prepare(
111	            "INSERT OR REPLACE INTO processing_ack (message_id, status, status_changed) VALUES (?, 'completed', datetime('now'))",
112	          )
113	          .run(row.id);
114	        outDb.close();
115	
116	        const parsed = JSON.parse(row.content);
117	        return parsed.frame as ResponseFrame;
118	      }
119	    } finally {
120	      inDb.close();
121	    }
122	
123	    Bun.sleepSync(500);
124	  }
125	
126	  return null;
127	}
128	
129	// ---------------------------------------------------------------------------
130	// Arg parsing (mirrors host-side client.ts)
131	// ---------------------------------------------------------------------------
132	
133	function parseArgv(argv: string[]): {
134	  command: string;
135	  args: Record<string, unknown>;
136	  json: boolean;
137	} {
138	  const positional: string[] = [];
139	  const args: Record<string, unknown> = {};
140	  let json = false;
141	
142	  for (let i = 0; i < argv.length; i++) {
143	    const a = argv[i];
144	    if (a === '--json') {
145	      json = true;
146	      continue;
147	    }
148	    if (a.startsWith('--')) {
149	      const key = a.slice(2);
150	      const next = argv[i + 1];
151	      if (next === undefined || next.startsWith('--')) {
152	        args[key] = true;
153	      } else {
154	        args[key] = next;
155	        i++;
156	      }
157	      continue;
158	    }
159	    positional.push(a);
160	  }
161	
162	  if (positional.length === 0) {
163	    process.stderr.write('ncl: missing command\n');
164	    printUsage();
165	    process.exit(2);
166	  }
167	
168	  // Join all positionals with dashes. The dispatcher trims the last
169	  // segment as a target ID if the full name isn't a registered command.
170	  const command = positional.join('-');
171	
172	  return { command, args, json };
173	}
174	
175	function printUsage(): void {
176	  process.stdout.write(
177	    ['Usage: ncl <command> [--key value ...] [--json]', '', 'Run `ncl help` to list available commands.', ''].join('\n'),
178	  );
179	}
180	
181	// ---------------------------------------------------------------------------
182	// Formatting (mirrors src/cli/format.ts on the host)
183	// ---------------------------------------------------------------------------
184	
185	function formatHuman(resp: ResponseFrame): string {
186	  if (!resp.ok) {
187	    return `error (${resp.error.code}): ${resp.error.message}\n`;
188	  }
189	
190	  const data = resp.data;
191	  if (!Array.isArray(data) || data.length === 0) {
192	    return JSON.stringify(data, null, 2) + '\n';
193	  }
194	
195	  const isFlat = data.every(
196	    (r) =>
197	      typeof r === 'object' &&
198	      r !== null &&
199	      !Array.isArray(r) &&
200	      Object.values(r as Record<string, unknown>).every((v) => typeof v !== 'object' || v === null),
201	  );
202	
203	  if (!isFlat) return JSON.stringify(data, null, 2) + '\n';
204	
205	  const keys = Object.keys(data[0] as Record<string, unknown>);
206	  const widths = keys.map((k) =>
207	    Math.max(k.length, ...data.map((r) => String((r as Record<string, unknown>)[k] ?? '').length)),
208	  );
209	
210	  const header = keys.map((k, i) => k.padEnd(widths[i])).join('  ');
211	  const sep = widths.map((w) => '-'.repeat(w)).join('  ');
212	  const rows = data.map((r) =>
213	    keys
214	      .map((k, i) => String((r as Record<string, unknown>)[k] ?? '').padEnd(widths[i]))
215	      .join('  '),
216	  );
217	
218	  return [header, sep, ...rows, ''].join('\n');
219	}
220	
221	// ---------------------------------------------------------------------------
222	// Main
223	// ---------------------------------------------------------------------------
224	
225	const argv = process.argv.slice(2);
226	
227	if (argv.length === 0 || argv[0] === '--help' || argv[0] === '-h') {
228	  printUsage();
229	  process.exit(0);
230	}
231	
232	const { command, args, json } = parseArgv(argv);
233	const requestId = generateId();
234	const req: RequestFrame = { id: requestId, command, args };
235	
236	writeRequest(req);
237	
238	const resp = pollResponse(requestId, 30_000);
239	
240	if (!resp) {
241	  process.stderr.write('ncl: command timed out after 30s\n');
242	  process.exit(2);
243	}
244	
245	if (json) {
246	  process.stdout.write(JSON.stringify(resp, null, 2) + '\n');
247	} else {
248	  const output = formatHuman(resp);
249	  if (!resp.ok) {
250	    process.stderr.write(output);
251	    process.exit(1);
252	  }
253	  process.stdout.write(output);
254	}
